import 'package:flutter/material.dart';

// The main function that starts the Flutter application.
void main() => runApp(MyApp());

// This is the root widget of the application. It's a StatelessWidget because its configuration is immutable.
class MyApp extends StatelessWidget {
	@override
	// The build method describes the part of the user interface represented by this widget.
	Widget build(BuildContext context) {
		// MaterialApp is a widget that wraps a number of widgets that are commonly required for an application implementing Material Design.
		return MaterialApp(home: CounterScreen()); // Sets the CounterScreen as the home page of the application.
	}
}

// StatefulWidget is a widget that has mutable state that can change over its lifetime.
class CounterScreen extends StatefulWidget {
	@override
	// Creates the mutable state for this widget.
	_CounterScreenState createState() => _CounterScreenState();
}

// This is the state class for the CounterScreen widget.
class _CounterScreenState extends State<CounterScreen> {
	// State variable to hold the counter value, initialized to 0.
	int _counter = 0;

	// Method to increment the counter value.
	void _incrementCounter() {
		// setState is called to notify the Flutter framework that the internal state of this widget has changed, triggering a UI rebuild.
		setState(() {
			_counter++; // Increments the counter variable.
		});
	}

	@override
	// The build method describes the part of the user interface represented by this widget.
	Widget build(BuildContext context) {
		// Scaffold implements the basic material design visual layout structure.
		return Scaffold(
			// The body property holds the main content of the Scaffold.
			body: Center(
				// Center widget centers its child within itself.
				child: Column(
					// Column widget arranges its children in a vertical line.
					mainAxisAlignment: MainAxisAlignment.center, // Centers the children along the main axis (vertically).
					children: [
						// Text widget to display the current counter value.
						Text("Counter: \$_counter"),
						// ElevatedButton is a Material Design elevated button.
						ElevatedButton(
							// onPressed is a callback function that is executed when the button is pressed.
							onPressed: _incrementCounter, // Calls the _incrementCounter method when the button is pressed.
							// The child widget displayed within the ElevatedButton.
							child: Text("Increment"),
						),
					],
				),
			),
		);
	}
}

