import 'package:flutter/material.dart';

// CounterModel is a class that extends ChangeNotifier, making it able to notify its listeners about changes.
class CounterModel extends ChangeNotifier {
	// Private variable to hold the counter value, initialized to 0.
	int _count = 0;

	// Getter method to access the current value of the counter.
	int get count => _count;

	// Method to increment the counter value.
	void increment() {
		_count++;
		// notifyListeners() is a method from ChangeNotifier that tells all the widgets listening to this model to rebuild themselves because the state has changed.
		notifyListeners();
	}
}

