void main() {
	runApp(
		// ChangeNotifierProvider is a provider from the provider package that provides an instance of a ChangeNotifier to its descendants.
		ChangeNotifierProvider(
			// create specifies how to create the value being provided. Here, it creates a new instance of CounterModel.
			create: (context) => CounterModel(),
			// child is the widget that will have access to the provided CounterModel instance.
			child: MyApp(),
		),
	);
}

